const form=document.getElementById("plasterForm"),result=document.getElementById("result");form&&form.addEventListener("submit",a=>{a.preventDefault();const s=parseFloat(document.getElementById("area").value)||0,t=parseFloat(document.getElementById("thick").value)||0,e=parseFloat(document.getElementById("rate").value)||0,n=parseFloat(document.getElementById("bagW").value)||0;if(s<=0||t<=0||e<=0||n<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите площадь, толщину, расход и вес мешка больше нуля.</p>';return}const l=s*t*e,c=Math.ceil(l/n),i=l/2e3;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Площадь</span><span class="val">${fmt(s)} м²</span></div>
        <div class="item"><span>Толщина слоя</span><span class="val">${fmt(t)} мм</span></div>
        <div class="item"><span>Смеси (при ${fmt(e)} кг/м²·мм)</span><span class="val">${fmt(l)} кг</span></div>
        <div class="item"><span>Объём (≈)</span><span class="val">${fmt(i)} м³</span></div>
        <div class="item total"><span>Мешков (по ${fmt(n)} кг)</span><span class="val">${fmt(c)} шт</span></div>
      </div>
    `});function fmt(a){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(a)}
